def run(ids, cache=None):
    """One forward pass. Returns (cache, logits); `cache` is passed to the forward as `cache_params`."""
    with torch.no_grad(), model.trace(ids, cache_params=cache, use_cache=True):
        out = model.output.save()
    return out["cache_params"], out["logits"]

def rec(cache, layer):
    """The recurrent state of one layer: (batch, d_inner, d_state)."""
    return cache.layers[layer].recurrent_states[0]

def conv(cache, layer):
    """The convolutional state of one layer: (batch, d_inner, conv_kernel)."""
    return cache.layers[layer].conv_states[0]

snap_cache, _ = run(corrupt_ids[:, : corrupt_ids.shape[1] - K])
corrupt_state = [(rec(snap_cache, L).clone(), conv(snap_cache, L).clone()) for L in range(N_LAYERS)]

def write_state(cache, states, layers=None, what="both"):
    for L in (range(N_LAYERS) if layers is None else layers):
        h, c = states[L]
        if what in ("both", "recurrent"):
            rec(cache, L).copy_(h)
        if what in ("both", "conv"):
            conv(cache, L).copy_(c)

noop_logits = continuation(corrupt_ids, K, lambda c: write_state(c, corrupt_state))

print("bit-identical:", torch.equal(noop_logits, corrupt_logits))
print("max |delta|  :", (noop_logits - corrupt_logits).abs().max().item())

OFFSETS = list(range(5))

grid = [[[0.0] * len(OFFSETS) for _ in range(N_LAYERS)] for _ in PAIRS]
for oi, off in enumerate(OFFSETS):
    sweep = restoration_sweep(offset=off, conditions=("recurrent",))
    for pi in range(len(PAIRS)):
        for L in range(N_LAYERS):
            grid[pi][L][oi] = sweep["recurrent"][pi][L]

grid_mean = [[statistics.mean(grid[p][L][oi] for p in range(len(PAIRS))) for oi in range(len(OFFSETS))]
             for L in range(N_LAYERS)]

peak = max(range(N_LAYERS), key=lambda L: statistics.mean(grid_mean[L][1:]))
print("peak layer:", peak)

ctrl = {c: [] for c in ("recurrent", "self", "random", "zero")}
for off in OFFSETS:
    s = restoration_sweep(offset=off, conditions=tuple(ctrl), layers=[peak])
    for c in ctrl:
        ctrl[c].append(statistics.mean(s[c][p][0] for p in range(len(PAIRS))))

print("split point   ", "  ".join(f"{o:>6d}" for o in OFFSETS))
for c in ctrl:
    print(f"{c:>14}", "  ".join(f"{v:+6.3f}" for v in ctrl[c]))
